from game import Board

DIRS = {"u": (-1, 0), "d": (1, 0), "l": (0, -1), "r": (0, 1)}

HELP = """Commands:
  <row> <col> <u|d|l|r>   swap cell with its neighbour in that direction
  <r1> <c1> <r2> <c2>     swap two adjacent cells
  h  help    s  stats    q  quit"""


def main():
    if os.name == "nt":
        os.system("")  # enable ANSI colours on Windows terminals
    board = Board()
    print("=== Candy Match ===  Form lines of 3+; cascades multiply your score!")
    print(HELP)
    board.render()
    while board.moves_left > 0:
        try:
            parts = input("\nMove> ").strip().lower().split()
        except (EOFError, KeyboardInterrupt):
            print("\nBye!")
            return
        if not parts:
            continue
        cmd = parts[0]
        if cmd == "q":
            break
        if cmd == "h":
            print(HELP)
            continue
        if cmd == "s":
            print(f"Score: {board.score}   Moves left: {board.moves_left}")
            continue
        try:
            nums = [int(p) for p in parts if p not in DIRS]
        except ValueError:
            print("Invalid input. Type 'h' for help.")
            continue
        if len(nums) == 2 and len(parts) == 3 and parts[2] in DIRS:
            dr, dc = DIRS[parts[2]]
            n = board.swap(nums[0], nums[1], nums[0] + dr, nums[1] + dc)
        elif len(nums) == 4 and len(parts) == 4:
            n = board.swap(*nums)
        else:
            print("Invalid input. Type 'h' for help.")
            continue
        if n:
            board.render()
            if n > 1:
                print(f"Chain reaction x{n}!")
            if not board.any_moves():
                print("No possible moves remain.")
                break
        else:
            print("Invalid swap — candies must be adjacent and form a match.")
    print(f"Game over! Final score: {board.score}")


if __name__ == "__main__":
    main()
